package com.apex.operations.console;
import static org.assertj.core.api.Assertions.*;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;
import com.apex.operations.contracts.*;import com.apex.operations.contracts.OwnerSnapshot.*;
class EvidenceCacheTest {
 OwnerSnapshot sample(Instant t,UUID epoch,String state){return new OwnerSnapshot(1,"test","order-cell","one",epoch,t,1000,"EXPLICIT_KEYS_PARTIAL_NO_HISTORY",List.of(new Fact(Kind.OUTBOX,new UUID(0,1),"owner",state,EvidenceClass.OWNER_COMMITTED_ROW,Certainty.VERIFIED_WITHIN_SCOPE,null)),List.of(),false,0,0);}
 @Test void staleRetainsLastFactAndOutOfOrderCannotReplaceCurrent(){var cache=new EvidenceCache();var t=Instant.now();var e=UUID.randomUUID();cache.accept(sample(t,e,"PUBLISHED_MARK"),t);cache.accept(sample(t.minusSeconds(2),e,"PENDING"),t);
 assertThat(cache.view("order-cell",t.plusSeconds(3)).freshness()).isEqualTo("STALE");assertThat(cache.view("order-cell",t).snapshot().facts().getFirst().state()).isEqualTo("PUBLISHED_MARK");assertThat(cache.view("order-cell",t).conflicts()).hasSize(1);}
 @Test void sameTimestampContradictionIsRetainedWithoutArrivalOrderAuthority(){var c=new EvidenceCache();var t=Instant.now();var e=UUID.randomUUID();c.accept(sample(t,e,"PENDING"),t);c.accept(sample(t,e,"PUBLISHED_MARK"),t);assertThat(c.view("order-cell",t).uncertainty()).isEqualTo("CONFLICTING");assertThat(c.view("order-cell",t).snapshot().facts().getFirst().state()).isEqualTo("PENDING");}
 @Test void missingFutureAndEpochAreExplicit(){var c=new EvidenceCache();var t=Instant.now();assertThat(c.view("order-cell",t).freshness()).isEqualTo("MISSING");c.accept(sample(t.plusSeconds(3),UUID.randomUUID(),"PENDING"),t);assertThat(c.view("order-cell",t).freshness()).isEqualTo("CLOCK_UNCERTAIN");}
 @Test void boundsRejectGiantAndDuplicateQuery(){assertThatThrownBy(()->new EvidenceQuery(Collections.nCopies(17,UUID.randomUUID()),List.of())).isInstanceOf(IllegalArgumentException.class);var id=UUID.randomUUID();assertThatThrownBy(()->new EvidenceQuery(List.of(id,id),List.of())).isInstanceOf(IllegalArgumentException.class);}
 @Test void allMutationsAndGiantQueriesDenied()throws Exception {var f=new ReadOnlyFilter();for(String method:List.of("POST","PUT","PATCH","DELETE","OPTIONS","HEAD")){var req=new org.springframework.mock.web.MockHttpServletRequest(method,"/ops/v1/events/x");var res=new org.springframework.mock.web.MockHttpServletResponse();f.doFilter(req,res,(a,b)->{throw new AssertionError();});assertThat(res.getStatus()).isEqualTo(405);}var r=new org.springframework.mock.web.MockHttpServletRequest("GET","/ops/v1/cells");r.setQueryString("x".repeat(129));var s=new org.springframework.mock.web.MockHttpServletResponse();f.doFilter(r,s,(a,b)->{throw new AssertionError();});assertThat(s.getStatus()).isEqualTo(400);}
}
